function construct_direct_gsn_endpoint_basis_i_ic_splus2(lambda, m, nu, omega)
    lambda = ComplexF64(lambda)
    m = Float64(m)
    nu = Float64(nu)
    omega = ComplexF64(omega)
    l2 = lambda * lambda
    l3 = l2 * lambda
    m2 = m * m
    m3 = m2 * m
    m4 = m3 * m
    o2 = omega * omega
    o3 = o2 * omega
    o4 = o3 * omega
    s1 = sin(nu)
    c1 = sqrt((1 - s1) * (1 + s1))
    sn = s1
    c = c1
    cp2 = c * c
    cp3 = cp2 * c
    cp4 = cp3 * c
    cp5 = cp4 * c
    cp6 = cp5 * c
    cp7 = cp6 * c
