    coeffs = Vector{ComplexF64}(undef, LEN_DIRECT_GSN_ENDPOINT_i_ic_splus2)
    _construct_direct_gsn_endpoint_basis_i_ic_splus2_block_1!(coeffs, lambda, m, nu, omega, l2, l3, m2, m3, m4, o2, o3, o4, s1, c1, sn, c, cp2, cp3, cp4, cp5, cp6, cp7, cp8, cp9, cp10, cp11, cp12, cp13, cp14, cp15, cp16, cp17, cp18)
